  l_no_match_department_id       employees.department_id%TYPE := -1;
  l_expected_existing            NUMBER;
  l_actual_existing              NUMBER;
  l_no_match_count               NUMBER;
  l_expected_no_match            NUMBER := 0;
  l_actual_no_match              NUMBER;
  l_expected_null                NUMBER := 0;
  l_actual_null                  NUMBER;
  l_failures                     PLS_INTEGER := 0;

  PROCEDURE check_number(
    p_label    IN VARCHAR2,
    p_expected IN NUMBER,
    p_actual   IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_label ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    ELSE
      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_label ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    END IF;
  END check_number;
BEGIN
  SAVEPOINT test_block_start;

  DBMS_OUTPUT.ENABLE(1000000);

  -- Check 1: a department_id that has at least one employee row.
  SELECT MIN(department_id)
    INTO l_existing_department_id
    FROM employees
   WHERE department_id IS NOT NULL;

  IF l_existing_department_id IS NULL THEN
    l_failures := l_failures + 1;
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: existing department_id check - no suitable row found in employees.department_id'
    );
  ELSE
    SELECT COUNT(*)
      INTO l_expected_existing
      FROM employees
     WHERE department_id = l_existing_department_id;

    l_actual_existing := HARNESS_APP.headcount(l_existing_department_id);

    check_number(
      p_label    => 'existing department_id=' || l_existing_department_id,
      p_expected => l_expected_existing,
      p_actual   => l_actual_existing
    );
  END IF;

  -- Check 2: a department_id that matches no employee row.
  SELECT COUNT(*)
    INTO l_no_match_count
    FROM employees
   WHERE department_id = l_no_match_department_id;

  IF l_no_match_count <> 0 THEN
    l_failures := l_failures + 1;
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: no-match department_id check - sentinel value ' ||
      l_no_match_department_id ||
      ' already exists in employees.department_id'
    );
  ELSE
    l_actual_no_match := HARNESS_APP.headcount(l_no_match_department_id);

    check_number(
      p_label    => 'no-match department_id=' || l_no_match_department_id,
      p_expected => l_expected_no_match,
      p_actual   => l_actual_no_match
    );
  END IF;

  -- Check 3: NULL argument. The function compares with =, so this matches no rows.
  l_actual_null := HARNESS_APP.headcount(NULL);

  check_number(
    p_label    => 'NULL department_id',
    p_expected => l_expected_null,
    p_actual   => l_actual_null
  );

  DBMS_OUTPUT.PUT_LINE('Failure count: ' || l_failures);

  ROLLBACK TO test_block_start;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed with ' || l_failures || ' failure(s)'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_block_start;
    RAISE;
END;
```

The block calls the stored function as `HARNESS_APP.headcount`; it does not copy the function body into the test. It checks three cases:

1. A real `department_id` found from `employees`, with the expected count computed by a separate `COUNT(*)` query using the same equality predicate the function uses.
2. A sentinel `department_id` value, `-1`, confirmed by a separate query to match no rows before calling the function. If that sentinel already exists, the check reports `FAIL` and counts as a failure rather than silently skipping.
3. A `NULL` argument. Because the function uses `department_id = p_department_id`, a `NULL` argument matches no rows, so the expected result is `0`, not a count of rows where `employees.department_id IS NULL`.

The block starts with a `SAVEPOINT`, rolls back to it at the end, and also rolls back to it if an unexpected exception occurs. It does not commit. I have not run this block.

